effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
int u_xlati3;
vec4 u_xlat4;
vec4 u_xlat5;
vec3 u_xlat6;
float u_xlat7;
vec2 u_xlat10;
bool u_xlatb10;
float u_xlat21;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + (-_center.xy);
    u_xlat21 = _resolution.y / _resolution.x;
    u_xlat0.z = u_xlat21 * u_xlat0.y;
    u_xlat7 = _angle * 0.0174532998;
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlat21 = float(int(_samples));
    u_xlat2 = u_xlat1;
    for(int u_xlati_loop_1 = 1 ; u_xlati_loop_1<int(_samples) ; u_xlati_loop_1++)
    {
        u_xlat10.x = float(u_xlati_loop_1);
        u_xlat10.x = u_xlat7 * u_xlat10.x;
        u_xlat10.x = u_xlat10.x / u_xlat21;
        u_xlat10.x = (-_angle) * 0.00872664992 + u_xlat10.x;
        u_xlat4.x = sin(u_xlat10.x);
        u_xlat5.x = cos(u_xlat10.x);
        u_xlat6.x = (-u_xlat4.x);
        u_xlat6.y = u_xlat5.x;
        u_xlat5.x = dot(u_xlat6.yx, u_xlat0.xz);
        u_xlat6.z = u_xlat4.x;
        u_xlat10.x = dot(u_xlat6.zy, u_xlat0.xz);
        u_xlat10.x = u_xlat10.x * _resolution.x;
        u_xlat5.y = u_xlat10.x / _resolution.y;
        u_xlat10.xy = u_xlat5.xy + _center.xy;
        u_xlat4 = texture(inputImg, u_xlat10.xy);
        u_xlat2 = u_xlat2 + u_xlat4;
    }
    u_xlat0 = u_xlat2 / vec4(u_xlat21);
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
